import React from 'react';
import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from './ui/card';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from './ui/tabs';
import { useAuth } from '../contexts/AuthContext';
import { subscriptionsService, type SubscriptionRequest } from '../services/subscriptions.service';
import { tenantsService } from '../services/tenants.service';
import { rolesService } from '../services/roles.service';
import { toast } from 'sonner';
import { api } from '../services/api';
import { TrialExtensionRequestsPanel } from './suscripciones/TrialExtensionRequestsPanel';
import { NovaSuiteIcon } from './ui/NovaIcons';
import { 
  CheckCircle2, 
  Clock, 
  XCircle, 
  Plus, 
  HandCoins, 
  ShieldCheck, 
  LayoutGrid, 
  Building2,
  Lock,
  Zap,
  DollarSign,
  Search,
  Check,
  Globe,
  Mail,
  User as UserIcon,
  MessageSquare,
  TrendingUp,
  Activity,
  Award,
  Edit2,
  Eye,
  Trash2,
  Users,
  FileText,
  Settings,
  BarChart3,
  CalendarDays,
  Briefcase,
  Package,
  Headphones,
  BellRing,
  X,
  KeyRound,
  BookOpen,
  Landmark,
  Scale,
  GraduationCap,
  LifeBuoy
} from 'lucide-react';
import { motion, AnimatePresence } from 'motion/react';
import { cn } from './ui/utils';
import { ConfirmDialog } from './ui/ConfirmDialog';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from './ui/dialog';
import { Label } from './ui/label';
import { Input } from './ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from './ui/select';
import { Textarea } from './ui/textarea';
import type { Submodule } from '../types/modules';
import { SIDEBAR_PERMISSION_SUBMODULES } from '../utils/sidebarPermissions';
import { storageService } from '../services/storage.service';
import { authService } from '../services/auth.service';
import { TenantSubscriptionView } from './suscripciones/TenantSubscriptionView';
import { getPasswordError, isValidEmail, normalizeEmail } from '../utils/accountValidation';
import { useTenantQuery, asList } from '../hooks/useTenantQuery';

const submodulesFor = (parent: string): Submodule[] => SIDEBAR_PERMISSION_SUBMODULES
  .filter((sub) => sub.parent === parent && sub.subscription !== false)
  .map((sub) => ({ ...sub, description: `Vista de ${sub.label}` }));

const AVAILABLE_MODULES = [
  { id: 'SALES', label: 'Ventas', icon: TrendingUp, description: 'Cotizaciones, Facturación y Clientes', submodules: submodulesFor('SALES') },
  { id: 'INVENTORY', label: 'Inventario', icon: Package, description: 'Stock, Almacenes y SKU', submodules: submodulesFor('INVENTORY') },
  { id: 'FINANCIAL', label: 'Finanzas', icon: DollarSign, description: 'Libro Mayor y Balance General', submodules: submodulesFor('FINANCIAL') },
  { id: 'PURCHASES', label: 'Compras', icon: HandCoins, description: 'Proveedores y Órdenes de Compra', submodules: submodulesFor('PURCHASES') },
  { id: 'HR', label: 'Recursos Humanos', icon: UserIcon, description: 'Nómina y Gestión de Empleados', submodules: submodulesFor('HR') },
  { id: 'ACTIVITIES', label: 'Actividades', icon: CalendarDays, description: 'Registro de Actividades', submodules: submodulesFor('ACTIVITIES') },
  { id: 'DOCUMENTS', label: 'Documentos', icon: FileText, description: 'Gestión Documental', submodules: submodulesFor('DOCUMENTS') },
  { id: 'TICKETS', label: 'Tickets y Soporte', icon: Headphones, description: 'Soporte y Atención' },
  { id: 'NOTIFICATIONS', label: 'Notificaciones', icon: BellRing, description: 'Alertas del sistema', submodules: submodulesFor('NOTIFICATIONS') },
  { id: 'REPORTS', label: 'Reportes', icon: BarChart3, description: 'Informes y Análisis', submodules: submodulesFor('REPORTS') },
  { id: 'ACCOUNTING', label: 'Contabilidad', icon: BookOpen, description: 'Plan de Cuentas, Asientos y Reportes Fiscales', submodules: submodulesFor('ACCOUNTING') },
  { id: 'CONFIGURATION', label: 'Configuración', icon: Settings, description: 'Ajustes del Sistema' },
  { id: 'FINANCING', label: 'Financiamiento PYME', icon: Landmark, description: 'Financiamiento y Créditos' },
  { id: 'LEGAL', label: 'Asesoría Legal', icon: Scale, description: 'Asesoría y Casos Legales' },
  { id: 'TRAINING', label: 'Centro de Capacitación', icon: GraduationCap, description: 'Cursos y Capacitaciones' },
  { id: 'SUPPORT', label: 'Soporte Técnico', icon: LifeBuoy, description: 'Soporte Técnico Especializado' },
  { id: 'NOVACHAT', label: 'Nova Suite', icon: NovaSuiteIcon, description: 'Bandeja multicanal y comunicación unificada' },
];

const SYSTEM_ROLE_OPTIONS = [
  { value: 'ADMIN', label: 'Administrador', description: 'Acceso total del tenant' },
  { value: 'EMPLOYEE', label: 'Empleado', description: 'Acceso operativo limitado' },
  { value: 'VIEWER', label: 'Visualizador', description: 'Solo lectura' },
];

const LEGACY_ROLE_MAP: Record<string, 'ADMIN' | 'EMPLOYEE' | 'VIEWER'> = {
  'super-admin': 'ADMIN',
  admin: 'ADMIN',
  gerente: 'EMPLOYEE',
  contador: 'EMPLOYEE',
  vendedor: 'EMPLOYEE',
  almacenero: 'EMPLOYEE',
  comprador: 'EMPLOYEE',
  empleado: 'EMPLOYEE',
  'rh-manager': 'EMPLOYEE',
};

export function SuscripcionesPage() {
  const { user, refreshEnabledModules, canPerform } = useAuth();
  const canViewCompany = canPerform('CONFIG_COMPANY', 'view');
  const canViewUsers = canPerform('CONFIG_USERS', 'view');
  const canViewRoles = canPerform('CONFIG_ROLES', 'view');
  const canViewSubscriptions = canPerform('SUBSCRIPTIONS', 'view');
  const [requests, setRequests] = useState<SubscriptionRequest[]>([]);
  const [tenants, setTenants] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [customRoles, setCustomRoles] = useState<any[]>([]);
  const [isTenantDialogOpen, setIsTenantDialogOpen] = useState(false);
  const [isRequestDialogOpen, setIsRequestDialogOpen] = useState(false);
  const [isUserDialogOpen, setIsUserDialogOpen] = useState(false);
  const [selectedTenant, setSelectedTenant] = useState<any>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [userForm, setUserForm] = useState({ name: '', email: '', password: '', role: 'EMPLOYEE' });
  const [tenantUsers, setTenantUsers] = useState<any[]>([]);
  const [editingUser, setEditingUser] = useState<any>(null);
  const [isDetailsDialogOpen, setIsDetailsDialogOpen] = useState(false);
  const [tenantDetails, setTenantDetails] = useState<any>(null);
  const [expandedModules, setExpandedModules] = useState<Record<string, boolean>>({});
  const [logoFile, setLogoFile] = useState<File | null>(null);
  const [logoPreview, setLogoPreview] = useState<string>('');
  const [uploading, setUploading] = useState(false);
  const [passwordDialogUser, setPasswordDialogUser] = useState<any>(null);
  const [newPassword, setNewPassword] = useState('');
  const [isChangingPassword, setIsChangingPassword] = useState(false);
  const [tenantAdminEmailError, setTenantAdminEmailError] = useState('');
  const [checkingTenantAdminEmail, setCheckingTenantAdminEmail] = useState(false);
  const [pendingDeleteTenant, setPendingDeleteTenant] = useState<{ id: string; name: string } | null>(null);

  // Form state for module request
  const [requestForm, setRequestForm] = useState({
    tenantId: '',
    module: '',
    price: 0,
    notes: ''
  });

  // Form states for new tenant
  const [tenantForm, setTenantForm] = useState({
    name: '',
    slug: '',
    adminName: '',
    adminEmail: '',
    adminPassword: '',
    industry: 'TECHNOLOGY',
    plan: 'BASIC',
    logo: '',
    customPrice: ''
  });

  useEffect(() => {
    const email = normalizeEmail(tenantForm.adminEmail);
    setTenantAdminEmailError('');
    if (!email || !isValidEmail(email)) {
      setCheckingTenantAdminEmail(false);
      return;
    }
    const currentEmail = normalizeEmail(selectedTenant?.users?.[0]?.email || '');
    if (selectedTenant && email === currentEmail) {
      setCheckingTenantAdminEmail(false);
      return;
    }
    const timer = window.setTimeout(async () => {
      setCheckingTenantAdminEmail(true);
      try {
        const response: any = await authService.checkEmail(email);
        const exists = response?.data?.exists ?? response?.exists;
        setTenantAdminEmailError(exists ? 'Este correo ya está en uso. Escribe otro.' : '');
      } catch {
        setTenantAdminEmailError('No se pudo verificar el correo. Intenta nuevamente.');
      } finally {
        setCheckingTenantAdminEmail(false);
      }
    }, 450);
    return () => window.clearTimeout(timer);
  }, [tenantForm.adminEmail, selectedTenant]);

  const { data: subscriptionData, isLoading: subscriptionLoading, refetch: refetchSubscriptions } = useTenantQuery(
    ['my-company', user?.tenantId || 'platform', user?.role || 'unknown'],
    async (signal) => {
      if (!user) return { requests: [], tenants: [], customRoles: [] };
      if (user.isPlatformAdmin) {
        const [reqs, allTenants, rolesRes] = await Promise.all([
          user.role === 'partner' ? subscriptionsService.getPartnerRequests(undefined, signal) : subscriptionsService.getAllRequests(undefined, signal),
          tenantsService.getAll(undefined, signal),
          // Los roles son propios de cada sucursal; el SuperAdmin no tiene
          // tenant operativo y no debe cargar roles con alcance null.
          Promise.resolve([]),
        ]);
        return { requests: asList(reqs), tenants: asList(allTenants), customRoles: asList(rolesRes) };
      }
      if (user.isTenantAdmin) {
        const [reqs, myTenants, rolesRes] = await Promise.all([
          canViewSubscriptions ? subscriptionsService.getAllRequests({ clientTenantId: user.tenantId } as any, signal) : Promise.resolve([]),
          canViewCompany ? tenantsService.getAll(undefined, signal) : Promise.resolve([]),
          canViewRoles ? rolesService.getAll({ clientTenantId: user.tenantId }, signal) : Promise.resolve([]),
        ]);
        return {
          requests: asList(reqs).filter((request: any) => request.clientTenantId === user.tenantId),
          tenants: asList(myTenants).filter((tenant: any) => tenant.id === user.tenantId),
          customRoles: asList(rolesRes),
        };
      }

      const [tenantRes, reqs, rolesRes] = await Promise.all([
        canViewCompany ? tenantsService.getOne(user.tenantId, signal) : Promise.resolve(null),
        canViewSubscriptions ? subscriptionsService.getAllRequests({ clientTenantId: user.tenantId } as any, signal) : Promise.resolve([]),
        canViewRoles ? rolesService.getAll({ clientTenantId: user.tenantId }, signal) : Promise.resolve([]),
      ]);
      return {
        requests: asList(reqs).filter((request: any) => request.clientTenantId === user.tenantId),
        tenants: tenantRes ? [tenantRes] : [],
        customRoles: asList(rolesRes),
      };
    },
    {
      enabled: Boolean(user && (user.isPlatformAdmin || user.isTenantAdmin || canViewCompany || canViewUsers || canViewRoles || canViewSubscriptions)),
      refetchInterval: user?.isPlatformAdmin ? 5000 : false,
      onError: (error) => toast.error(error.message || 'Error al cargar datos de Mi Empresa'),
    },
  );

  useEffect(() => {
    setLoading(subscriptionLoading);
    if (!subscriptionData) return;
    setRequests(subscriptionData.requests as SubscriptionRequest[]);
    setTenants(subscriptionData.tenants);
    setCustomRoles(subscriptionData.customRoles);
  }, [subscriptionData, subscriptionLoading]);

  const fetchData = async () => {
    setLoading(true);
    try {
      const refreshed = await refetchSubscriptions();
      if (refreshed.data) {
        setRequests(refreshed.data.requests as SubscriptionRequest[]);
        setTenants(refreshed.data.tenants);
        setCustomRoles(refreshed.data.customRoles);
      }
    } catch (error) {
      console.error('Error fetching subscription data:', error);
      toast.error('Error al cargar datos de suscripciones');
    } finally {
      setLoading(false);
    }
  };

  const inferSystemRoleFromCustomRole = (role: any): 'ADMIN' | 'EMPLOYEE' | 'VIEWER' => {
    const perms = Array.isArray(role?.permissions) ? role.permissions : [];
    if (perms.length === 0) return 'EMPLOYEE';

    const readCount = perms.filter((p: any) => p?.read).length;
    const writeCount = perms.filter((p: any) => p?.write).length;

    if (readCount > 0 && writeCount === 0) return 'VIEWER';
    if (writeCount > 0) return 'EMPLOYEE';
    return 'EMPLOYEE';
  };

  const resolveSelectedRoleToSystemRole = (selectedRole: string): 'ADMIN' | 'EMPLOYEE' | 'VIEWER' => {
    if (SYSTEM_ROLE_OPTIONS.some(r => r.value === selectedRole)) {
      return selectedRole as 'ADMIN' | 'EMPLOYEE' | 'VIEWER';
    }

    if (selectedRole.startsWith('legacy:')) {
      const legacyId = selectedRole.replace('legacy:', '');
      return LEGACY_ROLE_MAP[legacyId] || 'EMPLOYEE';
    }

    if (selectedRole.startsWith('custom:')) {
      const customId = selectedRole.replace('custom:', '');
      const customRole = customRoles.find((r: any) => r.id === customId);
      return inferSystemRoleFromCustomRole(customRole);
    }

    return 'EMPLOYEE';
  };

  const handleCreateTenant = async () => {
    const passwordError = getPasswordError(tenantForm.adminPassword);
    if (!tenantForm.name.trim() || !tenantForm.adminName.trim() || !isValidEmail(tenantForm.adminEmail) || tenantAdminEmailError || checkingTenantAdminEmail || passwordError) {
      toast.error(tenantAdminEmailError || passwordError || 'Completa los datos del administrador con un correo disponible');
      return;
    }
    try {
      setUploading(true);
      let logoUrl = tenantForm.logo || null;
      
      if (logoFile) {
        logoUrl = await storageService.uploadTenantLogo(logoFile, tenantForm.slug || 'temp');
      }
      
      await tenantsService.create({ ...tenantForm, adminEmail: normalizeEmail(tenantForm.adminEmail), logo: logoUrl || undefined });
      toast.success('Empresa creada exitosamente');
      setIsTenantDialogOpen(false);
      resetTenantForm();
      setLogoFile(null);
      setLogoPreview('');
      fetchData();
    } catch (error: any) {
      toast.error(error.message || 'Error al crear empresa');
    } finally {
      setUploading(false);
    }
  };

  const handleUpdateTenant = async () => {
    if (!selectedTenant) return;
    if (!isValidEmail(tenantForm.adminEmail) || tenantAdminEmailError || checkingTenantAdminEmail) {
      toast.error(tenantAdminEmailError || 'Escribe un correo válido y disponible para el administrador');
      return;
    }
    try {
      setUploading(true);
      let logoUrl = tenantForm.logo;
      
      if (logoFile) {
        logoUrl = await storageService.uploadTenantLogo(logoFile, selectedTenant.id);
      }
      
      await tenantsService.update(selectedTenant.id, { ...tenantForm, adminEmail: normalizeEmail(tenantForm.adminEmail), logo: logoUrl });
      toast.success('Información actualizada correctamente');
      setIsTenantDialogOpen(false);
      setSelectedTenant(null);
      setLogoFile(null);
      setLogoPreview('');
      fetchData();
    } catch (error: any) {
      toast.error(error.message || 'Error al actualizar información');
    } finally {
      setUploading(false);
    }
  };

  const handleDeleteTenant = async (id: string, name: string) => {
    setPendingDeleteTenant({ id, name });
  };

  const handleViewDetails = async (tenant: any) => {
    setTenantDetails(tenant);
    setIsDetailsDialogOpen(true);
  };

  const resetTenantForm = () => {
    setTenantForm({
      name: '',
      slug: '',
      adminName: '',
      adminEmail: '',
      adminPassword: '',
      industry: 'TECHNOLOGY',
      plan: 'BASIC',
      logo: '',
      customPrice: ''
    });
    setLogoFile(null);
    setLogoPreview('');
  };

  const openEditTenant = (tenant: any) => {
    setSelectedTenant(tenant);
    setTenantForm({
      name: tenant.name,
      slug: tenant.slug,
      adminName: tenant.users?.[0]?.name || '',
      adminEmail: tenant.users?.[0]?.email || '',
      adminPassword: '',
      industry: tenant.industry,
      plan: tenant.plan,
      logo: tenant.logo || '',
      customPrice: tenant.customPrice || ''
    });
    setLogoPreview(tenant.logo || '');
    setIsTenantDialogOpen(true);
  };

  const handleToggleModule = (tenantId: string, moduleName: string, currentlyActive: boolean) => {
    if (currentlyActive) {
      if (!user?.isPlatformAdmin) {
        toast.info('Solo administradores de NovaHub pueden desactivar módulos directamente');
        return;
      }
      handleDirectDisable(tenantId, moduleName);
      return;
    }

    if (user?.role === 'partner') {
      setRequestForm({
        tenantId,
        module: moduleName,
        price: 0,
        notes: ''
      });
      setIsRequestDialogOpen(true);
    } else if (user?.isPlatformAdmin) {
      handleDirectEnable(tenantId, moduleName);
    }
  };

  const handleDirectEnable = async (tenantId: string, moduleName: string) => {
    if (!user?.isPlatformAdmin) return;
    if (!tenantId) {
      toast.error('ID de empresa inválido. Por favor recarga la página.');
      return;
    }
    
    try {
      const res = await subscriptionsService.createRequest({
        clientTenantId: tenantId,
        requestedModule: moduleName,
        customPrice: 0,
        notes: 'Activación directa por Super Admin'
      });
      await subscriptionsService.updateRequestStatus(res.id, { status: 'APPROVED' });
      toast.success(`Módulo activado exitosamente`);
      fetchData();
      refreshEnabledModules();
    } catch (error: any) {
      console.error('Error activación:', error);
      toast.error(error.response?.data?.message || 'Error al activar módulo');
      fetchData();
    }
  };

  const handleDirectDisable = async (tenantId: string, moduleName: string) => {
    if (!user?.isPlatformAdmin) return;
    if (!tenantId) {
      toast.error('ID de empresa inválido. Por favor recarga la página.');
      return;
    }

    try {
      await subscriptionsService.toggleModuleStatus({
        clientTenantId: tenantId,
        module: moduleName,
        isActive: false,
        notes: 'Desactivación directa por Super Admin'
      });
      toast.success('Módulo desactivado exitosamente');
      fetchData();
      refreshEnabledModules();
    } catch (error: any) {
      console.error('Error desactivación:', error);
      toast.error(error?.message || 'Error al desactivar módulo');
      fetchData();
    }
  };

  const handleToggleAllSubmodules = async (tenantId: string, parentId: string, submodules: any[], currentlyAllActive: boolean) => {
    if (!user?.isPlatformAdmin) {
      toast.info('Solo administradores de NovaHub pueden realizar cambios masivos directos.');
      return;
    }
    
    try {
      toast.loading(currentlyAllActive ? 'Desactivando catálogo...' : 'Activando catálogo...', { id: 'batch-toggle' });
      
      // 1. Toggle parent module first
      if (currentlyAllActive) {
        await subscriptionsService.toggleModuleStatus({ clientTenantId: tenantId, module: parentId, isActive: false, notes: 'Desactivación masiva padre' });
      } else {
        const isParentActive = tenants.find((t: any) => t.id === tenantId)?.subscriptions?.some((s: any) => s.module === parentId && s.isActive);
        if (!isParentActive) {
           const res = await subscriptionsService.createRequest({ clientTenantId: tenantId, requestedModule: parentId, customPrice: 0, notes: 'Activación masiva padre' });
           await subscriptionsService.updateRequestStatus(res.id, { status: 'APPROVED' });
        }
      }

      // 2. Toggle submodules
      for (const sub of submodules) {
        if (currentlyAllActive) {
          await subscriptionsService.toggleModuleStatus({ clientTenantId: tenantId, module: sub.id, isActive: false, notes: 'Desactivación masiva' });
        } else {
          const isAlreadyActive = tenants.find((t: any) => t.id === tenantId)?.subscriptions?.some((s: any) => s.module === sub.id && s.isActive);
          if (!isAlreadyActive) {
             const res = await subscriptionsService.createRequest({ clientTenantId: tenantId, requestedModule: sub.id, customPrice: 0, notes: 'Activación masiva por admin' });
             await subscriptionsService.updateRequestStatus(res.id, { status: 'APPROVED' });
          }
        }
      }
      toast.success(currentlyAllActive ? 'Catálogo desactivado exitosamente' : 'Catálogo activado exitosamente', { id: 'batch-toggle' });
      fetchData();
      refreshEnabledModules();
    } catch (error) {
      console.error('Error operación masiva:', error);
      toast.error('Error en operación masiva', { id: 'batch-toggle' });
      fetchData();
    }
  };

  const handleChangePassword = async () => {
    const passwordError = getPasswordError(newPassword);
    if (passwordError) {
      toast.error(passwordError);
      return;
    }
    try {
      setIsChangingPassword(true);
      await tenantsService.updateUser(selectedTenant!.id, passwordDialogUser.id, { password: newPassword });
      toast.success('Contraseña actualizada correctamente');
      setPasswordDialogUser(null);
      setNewPassword('');
    } catch (error: any) {
      toast.error(error?.message || 'Error al cambiar la contraseña');
    } finally {
      setIsChangingPassword(false);
    }
  };

  const handleSubmitRequest = async () => {
    try {
      await subscriptionsService.createRequest({
        clientTenantId: requestForm.tenantId,
        requestedModule: requestForm.module,
        customPrice: requestForm.price,
        notes: requestForm.notes
      });
      toast.success('✅ Solicitud enviada - El Super Admin recibirá una notificación');
      setIsRequestDialogOpen(false);
      setRequestForm({ tenantId: '', module: '', price: 0, notes: '' });
      fetchData();
    } catch (error: any) {
      toast.error(error.response?.data?.message || 'Error al enviar solicitud');
    }
  };

  const handleApprove = async (id: string) => {
    try {
      await subscriptionsService.updateRequestStatus(id, { status: 'APPROVED' });
      toast.success('Suscripción aprobada y módulo habilitado');
      fetchData();
      refreshEnabledModules();
    } catch (error) {
      toast.error('Error al aprobar suscripción');
    }
  };

  const handleReject = async (id: string) => {
    try {
      await subscriptionsService.updateRequestStatus(id, { status: 'REJECTED' });
      toast.error('Suscripción rechazada');
      fetchData();
    } catch (error) {
      toast.error('Error al rechazar suscripción');
    }
  };

  const [filterTrial, setFilterTrial] = useState<'ALL' | 'TRIAL' | 'ACTIVE'>('ALL');

  const filteredTenants = tenants.filter(t => {
    const matchesSearch = t.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      t.slug.toLowerCase().includes(searchTerm.toLowerCase()) ||
      t.industry?.toLowerCase().includes(searchTerm.toLowerCase());
    if (!matchesSearch) return false;
    if (filterTrial === 'TRIAL') return t.implementationStatus === 'TRIAL' || t.plan === 'BASIC';
    if (filterTrial === 'ACTIVE') return t.implementationStatus !== 'TRIAL';
    return true;
  });

  const getIndustryIcon = (industry: string) => {
    switch (industry) {
      case 'ARCHITECTURE': return Globe;
      case 'RETAIL': return LayoutGrid;
      case 'SERVICES': return UserIcon;
      default: return Building2;
    }
  };

  const getPlanColor = (plan: string) => {
    switch (plan) {
      case 'BASIC': return 'bg-blue-500/10 text-blue-400 border-blue-500/20';
      case 'PROFESSIONAL': return 'bg-purple-500/10 text-purple-400 border-purple-500/20';
      case 'ENTERPRISE': return 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20';
      default: return 'bg-muted/30 text-muted-foreground border-border/50';
    }
  };

  if (user && !user.isPlatformAdmin) {
    const myTenant = tenants.find(t => t.id === user.tenantId);
    if (!myTenant) {
      return <div className="mx-auto flex min-h-[320px] max-w-3xl items-center justify-center p-6 text-center text-sm text-muted-foreground">{subscriptionLoading ? 'Cargando la información de Mi Empresa...' : 'No tienes acceso a la información de esta empresa.'}</div>;
    }
    return (
      <>
      <TenantSubscriptionView 
        tenant={myTenant} 
        availableModules={AVAILABLE_MODULES} 
        requests={requests.filter((r: any) => r.clientTenantId === user.tenantId)}
        customRoles={customRoles}
        onRefresh={fetchData}
        onRequestModule={(moduleId, notes) => {
          subscriptionsService.createRequest({
            clientTenantId: user.tenantId,
            requestedModule: moduleId,
            customPrice: 0,
            notes: notes
          }).then(() => {
            toast.success('Solicitud enviada correctamente');
            fetchData();
          }).catch((err: any) => {
            toast.error(err.response?.data?.message || 'Error al enviar solicitud');
          });
        }}
      />
    </>);
  }

  return (
    <div className="p-6 space-y-8 max-w-7xl mx-auto min-h-screen">
      {/* --- HEADER --- */}
      <motion.div 
        initial={{ opacity: 0, x: -20 }}
        animate={{ opacity: 1, x: 0 }}
        className="flex flex-col lg:flex-row lg:items-center justify-between gap-4"
      >
        <div>
          <h1 className="text-4xl font-black tracking-tighter text-foreground flex items-center gap-3 uppercase italic">
            <Zap className="size-10 text-primary fill-primary/20" />
            Control <span className="text-primary">Nova</span>Hub
          </h1>
          <div className="flex items-center gap-2 mt-2">
            <Badge className="bg-primary/10 text-primary border-primary/20 px-3 py-1 text-[10px] font-black uppercase tracking-widest">
              Tenancy Master Console
            </Badge>
            <span className="text-muted-foreground text-xs font-medium">
              V 2.4.0 — Aprovisionamiento Real
            </span>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <Dialog open={isTenantDialogOpen} onOpenChange={setIsTenantDialogOpen}>
            <DialogTrigger asChild>
              <Button className="bg-primary hover:bg-primary/90 text-primary-foreground gap-2 shadow-xl shadow-primary/40 px-8 h-12 rounded-2xl transition-all hover:scale-105 active:scale-95 font-bold">
                <Plus className="size-5" /> Registrar Empresa
              </Button>
            </DialogTrigger>
            <DialogContent className="border-border/50 sm:max-w-[500px] shadow-2xl">
              <DialogHeader>
                <DialogTitle className="text-2xl font-black italic uppercase tracking-tighter">{selectedTenant ? 'Editar Entidad' : 'Nueva Entidad Tenant'}</DialogTitle>
                <DialogDescription> Configura el entorno aislado para el cliente. </DialogDescription>
              </DialogHeader>
              <div className="grid gap-6 py-6">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label className="text-[10px] uppercase font-black tracking-widest text-muted-foreground ml-1">Nombre Comercial</Label>
                    <Input 
                      placeholder="Empresa S.A." 
                      className="bg-muted/10 border-border/50 h-11 rounded-xl" 
                      value={tenantForm.name}
                      onChange={e => {
                        const newName = e.target.value;
                        const autoSlug = newName.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
                        setTenantForm({
                          ...tenantForm, 
                          name: newName,
                          slug: autoSlug
                        });
                      }}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label className="text-[10px] uppercase font-black tracking-widest text-muted-foreground ml-1">URL Personalizada (slug)</Label>
                    <Input 
                      placeholder="mi-empresa (auto-generado del nombre)" 
                      className="bg-muted/10 border-border/50 h-11 rounded-xl" 
                      disabled={!!selectedTenant}
                      value={tenantForm.slug}
                      onChange={e => setTenantForm({...tenantForm, slug: e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, '-')})}
                    />
                    <p className="text-[9px] text-muted-foreground ml-1">{tenantForm.slug || 'auto'}.novahub.io</p>
                  </div>
                </div>
                <div className="space-y-2">
                  <Label className="text-[10px] uppercase font-black tracking-widest text-muted-foreground ml-1">Administrador de Cuenta</Label>
                  <div className="grid grid-cols-2 gap-4">
                    <Input 
                      placeholder="Nombre Completo" 
                      className="bg-muted/10 border-border/50 h-11 rounded-xl"
                      value={tenantForm.adminName}
                      onChange={e => setTenantForm({...tenantForm, adminName: e.target.value})}
                    />
                    <Input 
                      placeholder="correo@empresa.com" 
                      className={cn("bg-muted/10 border-border/50 h-11 rounded-xl", tenantAdminEmailError && 'border-destructive')}
                      value={tenantForm.adminEmail}
                      onChange={e => {
                        setTenantForm({...tenantForm, adminEmail: e.target.value});
                        setTenantAdminEmailError('');
                      }}
                    />
                  </div>
                  {!selectedTenant && (
                    <div className="col-span-2 space-y-2">
                      <Label className="text-[10px] uppercase font-black tracking-widest text-muted-foreground ml-1">Contraseña inicial</Label>
                      <Input
                        type="password"
                        placeholder="8 caracteres, mayúscula, número y símbolo"
                        className={cn("bg-muted/10 border-border/50 h-11 rounded-xl", getPasswordError(tenantForm.adminPassword) && 'border-destructive')}
                        value={tenantForm.adminPassword}
                        onChange={e => setTenantForm({...tenantForm, adminPassword: e.target.value})}
                      />
                      {getPasswordError(tenantForm.adminPassword) && <p className="text-xs text-destructive">{getPasswordError(tenantForm.adminPassword)}</p>}
                    </div>
                  )}
                  {tenantAdminEmailError && <p className="col-span-2 text-xs text-destructive">{tenantAdminEmailError}</p>}
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label className="text-[10px] uppercase font-black tracking-widest text-muted-foreground ml-1">Vertical de Industria</Label>
                    <Input 
                      placeholder="Ej: Retail, Manufactura, Tecnología, Salud..." 
                      className="bg-muted/10 border-border/50 h-11 rounded-xl"
                      value={tenantForm.industry}
                      onChange={e => setTenantForm({...tenantForm, industry: e.target.value})}
                    />
                    <p className="text-[9px] text-muted-foreground ml-1">Cualquiera de las 50+ industrias disponibles</p>
                  </div>
                  <div className="space-y-2">
                    <Label className="text-[10px] uppercase font-black tracking-widest text-muted-foreground ml-1">Plan de Facturación</Label>
                    <Select value={tenantForm.plan} onValueChange={v => setTenantForm({...tenantForm, plan: v})}>
                      <SelectTrigger className="bg-muted/10 border-border/50 h-11 rounded-xl">
                        <SelectValue placeholder="Seleccionar plan..." />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="BASIC">Básico ($29/mes) - Funcionalidades esenciales</SelectItem>
                        <SelectItem value="PROFESSIONAL">Profesional ($79/mes) - Para empresas en crecimiento</SelectItem>
                        <SelectItem value="ENTERPRISE">Enterprise ($199/mes) - Solución completa</SelectItem>
                        <SelectItem value="CUSTOM">Custom (A medida) - Personalizado según necesidades</SelectItem>
                      </SelectContent>
                    </Select>
                    
                    {tenantForm.plan === 'CUSTOM' && (
                      <div className="mt-3">
                        <Label className="text-[10px] uppercase font-black tracking-widest text-muted-foreground ml-1">Precio Custom (USD)</Label>
                        <Input 
                          type="number" 
                          min="0"
                          placeholder="Ej. 299"
                          className="bg-muted/10 border-border/50 h-11 rounded-xl mt-1"
                          value={tenantForm.customPrice || ''}
                          onChange={e => setTenantForm({...tenantForm, customPrice: e.target.value})}
                        />
                      </div>
                    )}
                    
                    <p className="text-[9px] text-muted-foreground ml-1 mt-1">Selecciona el plan de facturación mensual</p>
                  </div>
                </div>
                
                <div className="space-y-2">
                  <Label className="text-[10px] uppercase font-black tracking-widest text-muted-foreground ml-1">Logo de Empresa (Opcional)</Label>
                  <div className="flex items-center gap-4">
                    {(logoPreview || tenantForm.logo) && (
                      <img src={logoPreview || tenantForm.logo} alt="Logo preview" className="size-16 rounded-xl object-cover border-2 border-border/50" />
                    )}
                    <Input 
                      type="file" 
                      accept="image/*"
                      className="bg-muted/10 border-border/50 h-11 rounded-xl file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-bold file:bg-emerald-700 file:text-white hover:file:bg-emerald-800"
                      onChange={e => {
                        const file = e.target.files?.[0];
                        if (file) {
                          setLogoFile(file);
                          const reader = new FileReader();
                          reader.onloadend = () => setLogoPreview(reader.result as string);
                          reader.readAsDataURL(file);
                        }
                      }}
                    />
                  </div>
                  <p className="text-[9px] text-muted-foreground ml-1">PNG, JPG o WEBP - Máx. 2MB</p>
                </div>
              </div>
              <DialogFooter className="gap-3">
                <Button variant="outline" className="border-border/50 rounded-xl h-11" onClick={() => { setIsTenantDialogOpen(false); setSelectedTenant(null); resetTenantForm(); }}>Cancelar</Button>
                <Button className="bg-primary hover:bg-primary/90 text-primary-foreground rounded-xl h-11 px-8 font-bold" onClick={selectedTenant ? handleUpdateTenant : handleCreateTenant} disabled={uploading || checkingTenantAdminEmail || !!tenantAdminEmailError || !isValidEmail(tenantForm.adminEmail) || (!selectedTenant && !!getPasswordError(tenantForm.adminPassword))}>
                  {selectedTenant ? 'Guardar Cambios' : 'Crear Entidad'}
                </Button>
              </DialogFooter>
            </DialogContent>
          </Dialog>
        </div>
      </motion.div>

      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4">
        {[
          { label: 'Empresas Activas', value: (tenants || []).length, icon: Building2, color: 'text-blue-500', bg: 'bg-blue-500/10' },
          { label: 'Servicios Habilitados', value: (tenants || []).reduce((acc, t) => acc + (t.subscriptions?.length || 0), 0), icon: Zap, color: 'text-primary', bg: 'bg-primary/10' },
          { label: 'Pendientes Revisión', value: (requests || []).filter(r => r.status === 'PENDING').length, icon: Clock, color: 'text-orange-500', bg: 'bg-orange-500/10' },
          { label: 'Crecimiento Mes', value: '+12%', icon: TrendingUp, color: 'text-purple-500', bg: 'bg-purple-500/10' },
        ].map((stat, i) => (
          <motion.div 
            key={i}
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ delay: i * 0.1 }}
          >
            <Card className="bg-card/50 border-border/50 hover:border-primary/20 transition-all group overflow-hidden relative backdrop-blur-md rounded-2xl shadow-sm">
              <div className={cn("absolute -top-2 -right-2 p-3 opacity-5 group-hover:opacity-10 transition-opacity", stat.color)}>
                <stat.icon className="size-20" />
              </div>
              <CardContent className="p-5 flex items-center gap-5 relative z-10">
                <div className={cn("p-3 rounded-2xl", stat.bg, stat.color)}>
                  <stat.icon className="size-6" />
                </div>
                <div>
                  <p className="text-muted-foreground text-[10px] font-black uppercase tracking-widest">{stat.label}</p>
                  <p className="text-3xl font-black text-foreground tabular-nums tracking-tighter">{stat.value}</p>
                </div>
              </CardContent>
            </Card>
          </motion.div>
        ))}
      </div>

      <Dialog open={isRequestDialogOpen} onOpenChange={setIsRequestDialogOpen}>
        <DialogContent className="bg-card border-border text-card-foreground sm:max-w-[450px]">
          <DialogHeader>
            <DialogTitle>Solicitar Activación de Módulo</DialogTitle>
            <DialogDescription className="text-muted-foreground"> Envía una solicitud de habilitación para el cliente seleccionado. </DialogDescription>
          </DialogHeader>
          <div className="grid gap-5 py-4">
            <div className="flex items-center gap-4 p-3 rounded-xl bg-muted/10 border border-border/50">
              <div className="size-10 rounded-lg bg-primary/10 flex items-center justify-center text-primary">
                <Zap className="size-5" />
              </div>
              <div>
                <p className="text-xs font-black uppercase tracking-widest text-muted-foreground">Módulo a Habilitar</p>
                <p className="text-sm font-bold text-foreground">{AVAILABLE_MODULES.find(m => m.id === requestForm.module)?.label}</p>
              </div>
            </div>

            <div className="space-y-2">
              <Label>Precio de Venta Sugerido (USD)</Label>
              <div className="relative">
                <DollarSign className="absolute left-3 top-2.5 size-4 text-muted-foreground" />
                <Input 
                  type="number"
                  placeholder="0.00"
                  className="bg-muted/10 border-border/50 pl-9"
                  value={requestForm.price}
                  onChange={e => setRequestForm({...requestForm, price: Number(e.target.value)})}
                />
              </div>
              <p className="text-[10px] text-muted-foreground italic">Este precio será comunicado al cliente en su facturación.</p>
            </div>

            <div className="space-y-2">
              <Label>Notas o Requerimientos Especiales</Label>
              <Textarea 
                placeholder="Ej: El cliente necesita acceso a reportes personalizados..."
                className="bg-muted/10 border-border/50 min-h-[100px]"
                value={requestForm.notes}
                onChange={e => setRequestForm({...requestForm, notes: e.target.value})}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" className="border-border text-foreground hover:bg-muted/10" onClick={() => setIsRequestDialogOpen(false)}>Cancelar</Button>
            <Button className="bg-primary text-primary-foreground hover:bg-primary/90" onClick={handleSubmitRequest}>Enviar Solicitud</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Tabs defaultValue="active" className="w-full">
        <TabsList className="grid w-full grid-cols-3 lg:w-[600px] bg-muted/20 border border-border/50 p-1 h-12">
          <TabsTrigger value="active" className="text-muted-foreground hover:text-foreground hover:bg-muted/40 data-[state=active]:bg-primary data-[state=active]:text-primary-foreground uppercase text-[10px] font-black tracking-widest gap-2">
            <Building2 className="size-4" /> Gestión Empresas
          </TabsTrigger>
          <TabsTrigger value="requests" className="text-muted-foreground hover:text-foreground hover:bg-muted/40 data-[state=active]:bg-primary data-[state=active]:text-primary-foreground uppercase text-[10px] font-black tracking-widest gap-2">
            <Clock className="size-4" /> Solicitudes
            {requests.filter(r => r.status === 'PENDING').length > 0 && (
              <Badge className="bg-rose-500 text-[10px] size-5 p-0 flex items-center justify-center rounded-full ml-1 animate-pulse border-none">
                {requests.filter(r => r.status === 'PENDING').length}
              </Badge>
            )}
          </TabsTrigger>
          <TabsTrigger value="trial-extensions" className="text-muted-foreground hover:text-foreground hover:bg-muted/40 data-[state=active]:bg-primary data-[state=active]:text-primary-foreground uppercase text-[10px] font-black tracking-widest gap-2">
            <Clock className="size-4" /> Trial Ext.
          </TabsTrigger>
        </TabsList>

        <TabsContent value="active" className="mt-6 space-y-6">
          <div className="flex items-center gap-4 bg-muted/10 p-3 rounded-xl border border-border/50">
            <Search className="size-5 text-muted-foreground ml-2" />
            <Input 
              placeholder="Buscar por Empresa, Cliente o Industria..." 
              className="bg-transparent border-none focus-visible:ring-0 text-foreground placeholder:text-muted-foreground"
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex items-center gap-2">
            <button onClick={() => setFilterTrial('ALL')} className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${filterTrial === 'ALL' ? 'bg-primary text-primary-foreground' : 'bg-muted/50 text-muted-foreground hover:bg-muted'}`}>Todos</button>
                    <button onClick={() => setFilterTrial('TRIAL')} className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${filterTrial === 'TRIAL' ? 'bg-amber-700 text-white' : 'bg-muted/50 text-muted-foreground hover:bg-muted'}`}>Trial</button>
                    <button onClick={() => setFilterTrial('ACTIVE')} className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${filterTrial === 'ACTIVE' ? 'bg-emerald-700 text-white' : 'bg-muted/50 text-muted-foreground hover:bg-muted'}`}>Activas</button>
          </div>

          <div className="grid grid-cols-1 gap-6">
            {filteredTenants.map(tenant => {
              const IndIcon = getIndustryIcon(tenant.industry);
              return (
                <Card key={tenant.id} className="bg-card border-border/50 hover:border-primary/20 transition-all overflow-hidden group">
                  <div className="p-6">
                    <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
                      <div className="flex items-center gap-5">
                        <div className="size-16 rounded-2xl bg-muted/20 flex items-center justify-center border border-border group-hover:bg-primary/10 group-hover:border-primary/30 transition-all relative">
                          <IndIcon className="size-8 text-muted-foreground group-hover:text-primary" />
                          <div className="absolute -bottom-1 -right-1 size-5 rounded-full bg-background border border-border flex items-center justify-center">
                            <ShieldCheck className="size-3 text-primary" />
                          </div>
                        </div>
                        <div>
                          <div className="flex items-center gap-3">
                            <h2 className="text-xl font-bold text-foreground tracking-tight">{tenant.name}</h2>
                            <Badge variant="outline" className={cn("text-[10px] font-bold uppercase tracking-widest", getPlanColor(tenant.plan))}>
                              {tenant.plan}
                            </Badge>
                            {(tenant.implementationStatus === 'TRIAL' || tenant.plan === 'BASIC') && (
                              <div className="flex items-center gap-1">
                                <Badge variant="outline" className="text-[9px] text-amber-500 border-amber-500/30 bg-amber-500/5">
                                  {tenant.expiresAt ? `Exp: ${new Date(tenant.expiresAt).toLocaleDateString('es-NI')}` : 'Trial'}
                                </Badge>
                                <button onClick={async () => {
                                  try {
                                    await api.patch(`/tenants/${tenant.id}`, { expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString() });
                                    toast.success(`Trial extendido 7 días para ${tenant.name}`);
                                    fetchData();
                                  } catch (e: any) { toast.error(e?.response?.data?.message || 'Error'); }
                                }} className="px-2 py-0.5 rounded text-[9px] font-bold text-emerald-500 hover:bg-emerald-500/10 border border-emerald-500/30 transition-colors" title="Extender trial 7 días">
                                  +7 días
                                </button>
                              </div>
                            )}
                          </div>
                          <div className="flex flex-wrap items-center gap-4 mt-1 text-xs text-muted-foreground font-bold uppercase tracking-tighter">
                            <span className="flex items-center gap-1.5"><Globe className="size-3.5" /> {tenant.slug}.novahub.io</span>
                            <span className="flex items-center gap-1.5"><UserIcon className="size-3.5" /> {tenant._count?.users || 0} Usuarios</span>
                            <span className="flex items-center gap-1.5 text-emerald-500/50"><Zap className="size-3.5" /> {tenant.industry}</span>
                          </div>
                        </div>
                      </div>

                      <div className="flex items-center gap-2">
                        <Button variant="ghost" size="icon" className="text-muted-foreground hover:text-primary hover:bg-primary/10 rounded-xl" onClick={() => openEditTenant(tenant)}>
                          <Edit2 className="size-5" />
                        </Button>
                        <Button variant="ghost" size="icon" className="text-muted-foreground hover:text-blue-500 hover:bg-blue-500/10 rounded-xl" onClick={async () => { 
                            setSelectedTenant(tenant); 
                            setIsUserDialogOpen(true);
                            try {
                              const users = await tenantsService.getUsers(tenant.id);
                              setTenantUsers(Array.isArray(users) ? users : (users as any)?.data || []);
                            } catch (error: any) {
                              setTenantUsers(tenant.users || []);
                              toast.error(error?.message || 'No se pudieron cargar los usuarios del tenant');
                            }
                          }}>
                          <Users className="size-5" />
                        </Button>
                        <Button variant="ghost" size="icon" className="text-muted-foreground hover:text-purple-500 hover:bg-purple-500/10 rounded-xl" onClick={() => handleViewDetails(tenant)}>
                          <Eye className="size-5" />
                        </Button>
                        <Button variant="ghost" size="icon" className="text-muted-foreground hover:text-rose-500 hover:bg-rose-500/10 rounded-xl" onClick={() => handleDeleteTenant(tenant.id, tenant.name)}>
                          <Trash2 className="size-5" />
                        </Button>
                      </div>

                      <div className="bg-muted/30 dark:bg-black/40 p-3 rounded-2xl border border-border/50">
                        <p className="text-[10px] font-black uppercase text-muted-foreground/60 tracking-widest mb-2">Módulos Soportados</p>
                        <div className="grid grid-cols-2 lg:grid-cols-3 gap-2">
                          {AVAILABLE_MODULES.map(mod => {
                            const isActive = tenant.subscriptions?.some((s: any) => s.module === mod.id && s.isActive);
                            const isPending = requests.some(r => r.clientTenantId === tenant.id && r.requestedModule === mod.id && r.status === 'PENDING');
                            const isExpanded = expandedModules[`${tenant.id}-${mod.id}`];
                            const hasSubmodules = mod.submodules ? mod.submodules.length > 0 : false;
                            
                            const activeSubmodulesCount = hasSubmodules ? mod.submodules!.filter((sub: any) => tenant.subscriptions?.some((s: any) => s.module === sub.id && s.isActive)).length : 0;
                            const allSubmodulesActive = hasSubmodules ? activeSubmodulesCount === mod.submodules!.length : false;
                            const visualIsActive = hasSubmodules ? allSubmodulesActive : isActive;
                            const isPartial = hasSubmodules && !allSubmodulesActive && activeSubmodulesCount > 0;
                            
                            return (
                               <React.Fragment key={mod.id}>
                                  <div className="space-y-1">
                                    <div className="flex items-center gap-2">
                                      <button
                                        onClick={() => setExpandedModules(prev => ({ ...prev, [`${tenant.id}-${mod.id}`]: !isExpanded }))}
                                        disabled={isPending && !hasSubmodules}
                                        className={cn(
                                          "flex-1 flex items-center justify-between px-3 py-2 rounded-xl border text-[10px] font-bold uppercase tracking-tight transition-all",
                                          visualIsActive 
                                            ? "bg-primary text-primary-foreground border-primary/50 shadow-lg shadow-primary/10" 
                                            : isPending
                                              ? "bg-amber-500/20 text-amber-600 dark:text-amber-500 border-amber-500/30 animate-pulse"
                                              : isPartial 
                                                ? "bg-primary/20 text-primary border-primary/30"
                                                : "bg-muted/50 text-muted-foreground/60 border-border/50 hover:border-primary/30 hover:text-foreground/80"
                                        )}
                                      >
                                        <div className="flex items-center gap-2" onClick={(e) => {
                                          if (!hasSubmodules) {
                                            e.stopPropagation();
                                            handleToggleModule(tenant.id, mod.id, isActive);
                                          }
                                        }}>
                                          <mod.icon className={cn("size-3.5", visualIsActive ? "text-primary-foreground" : isPartial ? "text-primary" : "text-muted-foreground/50")} />
                                          {mod.label}
                                          {visualIsActive && !hasSubmodules && <Check className="size-3 ml-1" />}
                                          {isPending && !hasSubmodules && <Clock className="size-3 ml-1" />}
                                        </div>
                                        <div className="flex items-center gap-2">
                                          {hasSubmodules && (
                                            <div className="flex items-center gap-1.5" onClick={(e) => {
                                              e.stopPropagation();
                                              handleToggleAllSubmodules(tenant.id, mod.id, mod.submodules!, allSubmodulesActive);
                                            }}>
                                              <div className={cn(
                                                "flex items-center justify-center p-1 rounded-md transition-all",
                                                visualIsActive ? "bg-white/20 hover:bg-white/30 text-primary-foreground" : "bg-muted dark:bg-black/40 hover:bg-primary hover:text-primary-foreground border border-border/50"
                                              )} title={visualIsActive ? "Desactivar Todo" : "Activar Todo"}>
                                                <Zap className={cn("size-3", isPartial && !visualIsActive ? "text-primary group-hover:text-primary-foreground" : "")} />
                                              </div>
                                            </div>
                                          )}
                                          <div className={cn("p-1 transition-transform", isExpanded ? "rotate-180" : "rotate-0")}>
                                            {hasSubmodules && <span className="opacity-70 text-[10px]">▼</span>}
                                          </div>
                                        </div>
                                      </button>
                                    </div>

                                    {hasSubmodules && isExpanded && (
                                      <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }} className="pl-6 space-y-1">
                                        {mod.submodules!.map((sub: Submodule) => {
                                          const subIsActive = tenant.subscriptions?.some((s: any) => s.module === sub.id && s.isActive);
                                          const subIsPending = requests.some(r => r.clientTenantId === tenant.id && r.requestedModule === sub.id && r.status === 'PENDING');
                                          return (
                                            <button
                                              key={sub.id}
                                              onClick={() => handleToggleModule(tenant.id, sub.id, subIsActive)}
                                              disabled={subIsPending}
                                              className={cn(
                                                "w-full flex items-center gap-2 px-3 py-1.5 rounded-lg border text-[9px] font-bold uppercase tracking-tight transition-all",
                                                subIsActive 
                                                  ? "bg-primary/80 text-primary-foreground border-primary/40" 
                                                  : subIsPending
                                                    ? "bg-amber-500/15 text-amber-600 dark:text-amber-500 border-amber-500/20 animate-pulse"
                                                    : "bg-muted/30 text-muted-foreground/50 border-border/30 hover:border-primary/20 hover:text-foreground/70"
                                              )}
                                              title={sub.description}
                                            >
                                              <span className="size-1.5 rounded-full bg-current" />
                                              {sub.label}
                                              {subIsActive && <Check className="size-2.5 ml-auto" />}
                                              {subIsPending && <Clock className="size-2.5 ml-auto" />}
                                            </button>
                                          );
                                        })}
                                      </motion.div>
                                    )}
                                  </div>
                                </React.Fragment>
                            );
                          })}
                        </div>
                      </div>
                    </div>
                  </div>
                </Card>
              );
            })}
          </div>
        </TabsContent>

        <TabsContent value="requests" className="mt-6">
          <div className="grid grid-cols-1 gap-4">
            {requests.length === 0 ? (
              <Card className="bg-card border-dashed border-border/50 py-20">
                <div className="flex flex-col items-center justify-center text-center">
                  <Clock className="size-12 text-muted-foreground/30 mb-4" />
                  <p className="text-muted-foreground font-bold uppercase tracking-widest text-xs">No hay solicitudes pendientes en este momento.</p>
                </div>
              </Card>
            ) : (
              requests.map((req) => (
                <Card key={req.id} className="bg-card border-border/50 overflow-hidden hover:border-primary/30 transition-all group">
                  <div className="flex flex-col md:flex-row items-center p-6 gap-6">
                    <div className="size-14 rounded-2xl bg-primary/10 flex items-center justify-center border border-primary/20 shrink-0">
                      <LayoutGrid className="size-7 text-primary" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <h3 className="text-lg font-bold text-foreground uppercase tracking-tight">{req.requestedModule}</h3>
                        <Badge variant="outline" className={cn(
                          "uppercase text-[10px] font-black tracking-widest",
                          req.status === 'PENDING' ? "text-amber-500 border-amber-500/30 bg-amber-500/5" :
                          req.status === 'APPROVED' ? "text-emerald-500 border-emerald-500/30 bg-emerald-500/5" :
                          "text-rose-500 border-rose-500/30 bg-rose-500/5"
                        )}>
                          {req.status}
                        </Badge>
                      </div>
                      <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-muted-foreground uppercase font-bold tracking-tighter">
                        <span className="flex items-center gap-1"><Building2 className="size-3" /> {req.clientTenant?.name}</span>
                        <span className="flex items-center gap-1 text-primary/80"><DollarSign className="size-3" /> Precio Proyectado: ${req.customPrice || 0}</span>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                       {user?.isPlatformAdmin && req.status === 'PENDING' && (
                        <>
                          <Button variant="outline" size="sm" onClick={() => handleReject(req.id)} className="bg-rose-500/10 text-rose-500 border-rose-500/20 hover:bg-rose-700 hover:text-white uppercase text-[10px] font-black px-4">Rechazar</Button>
                          <Button size="sm" onClick={() => handleApprove(req.id)} className="bg-primary hover:bg-primary/90 text-primary-foreground shadow-lg shadow-primary/20 uppercase text-[10px] font-black px-4">Aprobar</Button>
                        </>
                       )}
                    </div>
                  </div>
                </Card>
              ))
            )}
          </div>
        </TabsContent>
        <TabsContent value="trial-extensions" className="mt-6">
          <TrialExtensionRequestsPanel />
        </TabsContent>
      </Tabs>

      <Dialog open={isUserDialogOpen} onOpenChange={setIsUserDialogOpen}>
        <DialogContent className="sm:max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Users className="size-5 text-blue-500" />
              Gestión de Usuarios: {selectedTenant?.name}
            </DialogTitle>
            <DialogDescription>Administra usuarios, roles y accesos de esta empresa.</DialogDescription>
          </DialogHeader>
          <div className="py-4 space-y-4">
            {tenantUsers.length > 0 ? tenantUsers.map((u: any) => (
              <div key={u.id} className="p-4 rounded-2xl bg-muted/10 border border-border/50 space-y-3">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className={`size-10 rounded-full flex items-center justify-center font-bold text-sm ${u.isActive ? 'bg-primary/10 text-primary' : 'bg-red-500/10 text-red-400'}`}>
                      {u.name?.charAt(0) || '?'}
                    </div>
                    <div>
                      <p className="font-bold text-foreground text-sm">{u.name}</p>
                      <p className="text-xs text-muted-foreground">{u.email}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <Badge variant="outline" className={`text-[10px] font-black uppercase tracking-widest px-2 py-0.5 ${u.isActive ? 'bg-emerald-500/10 text-emerald-500 border-emerald-500/30' : 'bg-red-500/10 text-red-400 border-red-400/30'}`}>
                      {u.isActive ? 'Activo' : 'Inactivo'}
                    </Badge>
                      <button onClick={async () => {
                        try {
                          await api.patch(`/tenants/${selectedTenant.id}/users/${u.id}`, { isActive: !u.isActive });
                          toast.success(u.isActive ? 'Usuario desactivado' : 'Usuario activado');
                          setTenantUsers(prev => prev.map(p => p.id === u.id ? { ...p, isActive: !p.isActive } : p));
                        } catch (e: any) { toast.error(e?.response?.data?.message || e?.message || 'Error'); }
                      }} className={`p-1.5 rounded-lg transition-colors ${u.isActive ? 'text-rose-500 hover:bg-rose-500/10' : 'text-emerald-500 hover:bg-emerald-500/10'}`}
                      title={u.isActive ? 'Desactivar usuario' : 'Activar usuario'}>
                        {u.isActive ? <X className="size-3.5" /> : <Check className="size-3.5" />}
                      </button>
                    <Button variant="ghost" size="icon" className="size-6 text-muted-foreground hover:text-primary hover:bg-primary/10 rounded-full" onClick={() => setPasswordDialogUser(u)} title="Cambiar Contraseña">
                      <KeyRound className="size-3" />
                    </Button>
                  </div>
                </div>
              </div>
            )) : <p className="text-center py-10 text-muted-foreground italic text-xs">No hay usuarios registrados</p>}
          </div>
          <DialogFooter>
            <Button variant="outline" className="w-full rounded-xl" onClick={() => setIsUserDialogOpen(false)}>Cerrar Panel</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={!!passwordDialogUser} onOpenChange={(open) => !open && setPasswordDialogUser(null)}>
        <DialogContent className="sm:max-w-md border-border/50">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <KeyRound className="size-5 text-primary" />
              Cambiar Contraseña
            </DialogTitle>
            <DialogDescription>
              Introduce una nueva contraseña para el usuario <span className="font-bold text-foreground">{passwordDialogUser?.name}</span> ({passwordDialogUser?.email}).
            </DialogDescription>
          </DialogHeader>
          <div className="py-4 space-y-2">
            <Label className="text-[10px] uppercase font-black tracking-widest text-muted-foreground ml-1">Nueva Contraseña</Label>
            <Input 
              type="password" 
              placeholder="8 caracteres, mayúscula, número y símbolo" 
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              className={cn("bg-muted/10 border-border/50 h-11 rounded-xl", getPasswordError(newPassword) && 'border-destructive')}
            />
            {getPasswordError(newPassword) && <p className="text-xs text-destructive">{getPasswordError(newPassword)}</p>}
          </div>
          <DialogFooter className="gap-3">
            <Button variant="outline" className="border-border/50 rounded-xl h-11" onClick={() => setPasswordDialogUser(null)} disabled={isChangingPassword}>Cancelar</Button>
            <Button className="bg-primary hover:bg-primary/90 text-primary-foreground rounded-xl h-11 px-8 font-bold" onClick={handleChangePassword} disabled={isChangingPassword || !!getPasswordError(newPassword)}>
              {isChangingPassword ? 'Guardando...' : 'Guardar Contraseña'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={isDetailsDialogOpen} onOpenChange={setIsDetailsDialogOpen}>
        <DialogContent className="sm:max-w-4xl max-h-[90vh] overflow-y-auto border-border/50">
          <DialogHeader>
            <DialogTitle className="text-2xl font-black italic uppercase tracking-tighter flex items-center gap-3">
              <Building2 className="size-6 text-primary" />
              Detalles: {tenantDetails?.name}
            </DialogTitle>
          </DialogHeader>
          {tenantDetails && (
            <div className="py-4 space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <Card className="bg-muted/10 border-border/50 shadow-none">
                  <CardContent className="p-4 space-y-4">
                    <h3 className="font-bold text-sm uppercase tracking-widest text-muted-foreground flex items-center gap-2">
                      <Building2 className="size-4" /> Información General
                    </h3>
                    <div className="space-y-2 text-sm">
                      <div className="flex justify-between items-center border-b border-border/50 pb-2">
                        <span className="text-muted-foreground">Nombre:</span>
                        <span className="font-bold">{tenantDetails.name}</span>
                      </div>
                      <div className="flex justify-between items-center border-b border-border/50 pb-2">
                        <span className="text-muted-foreground">URL:</span>
                        <span className="font-bold">{tenantDetails.slug}.novahub.io</span>
                      </div>
                      <div className="flex justify-between items-center border-b border-border/50 pb-2">
                        <span className="text-muted-foreground">Industria:</span>
                        <span className="font-bold capitalize">{tenantDetails.industry?.toLowerCase()}</span>
                      </div>
                      <div className="flex justify-between items-center">
                        <span className="text-muted-foreground">Plan:</span>
                        <Badge variant="outline" className={getPlanColor(tenantDetails.plan)}>
                          {tenantDetails.plan}
                        </Badge>
                      </div>
                    </div>
                  </CardContent>
                </Card>

                <Card className="bg-muted/10 border-border/50 shadow-none">
                  <CardContent className="p-4 space-y-4">
                    <h3 className="font-bold text-sm uppercase tracking-widest text-muted-foreground flex items-center gap-2">
                      <Users className="size-4" /> Usuarios y Accesos
                    </h3>
                    <div className="space-y-2 text-sm">
                      <div className="flex justify-between items-center border-b border-border/50 pb-2">
                        <span className="text-muted-foreground">Total Usuarios:</span>
                        <span className="font-bold">{tenantDetails._count?.users || tenantDetails.users?.length || 0}</span>
                      </div>
                      {tenantDetails.users && tenantDetails.users.length > 0 ? (
                        <>
                          <div className="flex justify-between items-center border-b border-border/50 pb-2">
                            <span className="text-muted-foreground">Admin Principal:</span>
                            <span className="font-bold">{tenantDetails.users[0]?.name}</span>
                          </div>
                          <div className="flex justify-between items-center">
                            <span className="text-muted-foreground">Email Admin:</span>
                            <span className="font-bold">{tenantDetails.users[0]?.email}</span>
                          </div>
                        </>
                      ) : (
                         <div className="text-xs text-muted-foreground italic text-center py-2">
                           No hay datos de usuarios detallados.
                         </div>
                      )}
                    </div>
                  </CardContent>
                </Card>
              </div>

              <div className="space-y-3">
                <h3 className="font-bold text-sm uppercase tracking-widest text-muted-foreground flex items-center gap-2">
                  <Zap className="size-4" /> Módulos Activos
                </h3>
                <div className="flex flex-wrap gap-2">
                  {tenantDetails.subscriptions?.filter((s: any) => s.isActive).length > 0 ? (
                    tenantDetails.subscriptions.filter((s: any) => s.isActive).map((sub: any) => {
                      // Buscar en módulos principales
                      let mod = AVAILABLE_MODULES.find(m => m.id === sub.module);
                      let label = mod?.label;
                      // Si no está, buscar en submódulos
                      if (!mod) {
                        AVAILABLE_MODULES.forEach(m => {
                          if (m.submodules) {
                            const found = m.submodules.find(sm => sm.id === sub.module);
                            if (found) label = found.label;
                          }
                        });
                      }
                      return (
                        <Badge key={sub.id} className="bg-primary/10 text-primary border-primary/20 px-3 py-1">
                          {label || sub.module}
                        </Badge>
                      );
                    })
                  ) : (
                    <p className="text-xs text-muted-foreground italic bg-muted/50 w-full p-3 rounded-lg text-center border border-dashed border-border/50">No hay módulos activos para esta empresa.</p>
                  )}
                </div>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" className="w-full rounded-xl" onClick={() => setIsDetailsDialogOpen(false)}>Cerrar</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      <ConfirmDialog
        open={pendingDeleteTenant !== null}
        onOpenChange={(open) => !open && setPendingDeleteTenant(null)}
        title={`¿Eliminar "${pendingDeleteTenant?.name}"?`}
        description="Esta acción NO se puede deshacer. Se eliminarán todos los datos asociados a esta empresa."
        confirmLabel="Eliminar"
        variant="destructive"
        onConfirm={async () => {
          try {
            if (!pendingDeleteTenant) return;
            await tenantsService.delete(pendingDeleteTenant.id);
            toast.success('Empresa eliminada permanentemente');
            fetchData();
          } catch (error) {
            toast.error('Error al eliminar empresa');
          } finally {
            setPendingDeleteTenant(null);
          }
        }}
      />
    </div>
  );
}
